import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { ErrorCode } from "../utils/error-codes.ts";
import { sanitizeContent, validateRoomId, validateMessageId } from "../utils/validator.ts";
import { GLOBAL_RATE_LIMITER } from "../utils/rate-limiter.ts";
import { EnhancedApi, PaginationDefaults, MessageLimits } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export interface IChatroom {
    room_id: string;
    name: string;
    topic?: string;
    member_count: number;
    is_direct: boolean;
    is_encrypted: boolean;
    unread_count: number;
    last_message?: {
        content: string;
        sender: string;
        timestamp: string;
    };
    created_at: string;
    state: "active" | "archived";
}

export interface IChatroomParams {
    user_id?: string;
    state?: "active" | "archived" | "all";
    page?: number;
    limit?: number;
}

export interface IUnreadCount {
    total_unread: number;
    by_room: { room_id: string; unread: number }[];
}

export interface IPagination {
    page: number;
    limit: number;
    total: number;
    has_more: boolean;
}

export interface IMessage {
    message_id: string;
    room_id: string;
    content: string;
    type: string;
    sender: string;
    timestamp: string;
    reply_to?: string;
    is_deleted: boolean;
}

export interface IMessageParams {
    limit?: number;
    before?: string;
    after?: string;
}

export interface ISearchMessagesParams {
    query: string;
    page?: number;
    limit?: number;
}

export interface IChatroomApi {
    getChatrooms(params?: IChatroomParams): Promise<IChatroom[]>;
    getUnreadCount(): Promise<IUnreadCount>;
    getChatroomDetail(roomId: string): Promise<IChatroom | null>;
    leaveChatroom(roomId: string): Promise<boolean>;
    markAsRead(roomId: string): Promise<boolean>;
    getMessages(roomId: string, params?: IMessageParams): Promise<{ messages: IMessage[]; has_more: boolean }>;
    sendMessage(roomId: string, content: string, type?: string, replyTo?: string): Promise<IMessage>;
    deleteMessage(roomId: string, messageId: string): Promise<boolean>;
    searchMessages(roomId: string, params: ISearchMessagesParams): Promise<{ messages: IMessage[]; total: number }>;
}

export class ChatroomApi extends BaseApi implements IChatroomApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    private checkRateLimit(operation: string): void {
        const { allowed, resetAt } = GLOBAL_RATE_LIMITER.checkLimit(`chatroom:${operation}`);
        if (!allowed) {
            const retryAfter = Math.ceil((resetAt - Date.now()) / 1000);
            this.throwRateLimitError(retryAfter);
        }
    }

    /**
     * Retrieves a paginated list of chatrooms for the current user.
     *
     * @param params - Optional parameters for filtering and pagination
     * @param params.state - Filter by chatroom state (active, archived, or all)
     * @param params.page - Page number for pagination (default: 1)
     * @param params.limit - Number of items per page (default: 50, max: 1000)
     * @returns Promise resolving to array of chatrooms
     * @throws SynapseEnhancedError on API failure
     */
    public async getChatrooms(params?: IChatroomParams): Promise<IChatroom[]> {
        this.checkRateLimit("getChatrooms");
        const queryParams: Record<string, string | number | boolean | undefined> = {
            user_id: params?.user_id,
            state: params?.state || "active",
            page: params?.page || PaginationDefaults.PAGE,
            limit: params?.limit || PaginationDefaults.LIMIT,
        };

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                chatrooms?: IChatroom[];
                pagination?: IPagination;
            };
            error?: string;
        }>(EnhancedApi.CHATROOMS, queryParams);

        const data = handleApiResponse(response, "Failed to get chatrooms");
        return data.chatrooms || [];
    }

    /**
     * Retrieves the total unread message count across all chatrooms.
     *
     * @returns Promise resolving to unread count object with total and per-room breakdown
     * @throws SynapseEnhancedError on API failure
     */
    public async getUnreadCount(): Promise<IUnreadCount> {
        this.checkRateLimit("getUnreadCount");
        const response = await this.httpClient.get<{
            status: string;
            data?: {
                total_unread?: number;
                by_room?: { room_id: string; unread: number }[];
            };
            error?: string;
        }>(EnhancedApi.CHATROOMS_UNREAD);

        const data = handleApiResponse(response, "Failed to get unread count");

        return {
            total_unread: data.total_unread || 0,
            by_room: data.by_room || [],
        };
    }

    /**
     * Retrieves detailed information about a specific chatroom.
     *
     * @param roomId - The Matrix room ID (e.g., "!roomid:example.com")
     * @returns Promise resolving to chatroom details or null if not found
     * @throws SynapseEnhancedError on API failure (other than not found)
     */
    public async getChatroomDetail(roomId: string): Promise<IChatroom | null> {
        validateRoomId(roomId);

        try {
            const response = await this.httpClient.get<{
                status: string;
                data?: IChatroom;
                error?: string;
            }>(`${EnhancedApi.CHATROOMS}/${roomId}`);

            return handleApiResponse(response, "Failed to get chatroom detail");
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("not found") || error.message.includes("not exist"))
            ) {
                return null;
            }
            throw error;
        }
    }

    /**
     * Leaves a chatroom, removing the user from the room members.
     *
     * @param roomId - The Matrix room ID to leave
     * @returns Promise resolving to true on success
     * @throws SynapseEnhancedError on API failure
     */
    public async leaveChatroom(roomId: string): Promise<boolean> {
        validateRoomId(roomId);
        this.checkRateLimit("leaveChatroom");

        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(`${EnhancedApi.CHATROOMS}/${roomId}/leave`, {});

        handleApiResponse(response, "Failed to leave chatroom");
        return true;
    }

    /**
     * Marks all messages in a chatroom as read.
     *
     * @param roomId - The Matrix room ID to mark as read
     * @returns Promise resolving to true on success
     * @throws SynapseEnhancedError on API failure
     */
    public async markAsRead(roomId: string): Promise<boolean> {
        validateRoomId(roomId);
        this.checkRateLimit("markAsRead");

        const response = await this.httpClient.post<{
            status: string;
            error?: string;
        }>(`${EnhancedApi.CHATROOMS}/${roomId}/read`, {});

        handleApiResponse(response, "Failed to mark chatroom as read");
        return true;
    }

    /**
     * Retrieves messages from a chatroom with pagination support.
     *
     * @param roomId - The Matrix room ID to fetch messages from
     * @param params - Optional pagination parameters
     * @param params.limit - Maximum number of messages to return (default: 50)
     * @param params.before - Event ID to fetch messages before
     * @param params.after - Event ID to fetch messages after
     * @returns Promise resolving to messages array and has_more flag
     * @throws SynapseEnhancedError on API failure
     */
    public async getMessages(
        roomId: string,
        params?: IMessageParams,
    ): Promise<{ messages: IMessage[]; has_more: boolean }> {
        validateRoomId(roomId);
        this.checkRateLimit("getMessages");

        const queryParams: Record<string, string | number | undefined> = {
            room_id: roomId,
        };
        if (params?.limit !== undefined) queryParams.limit = params.limit;
        if (params?.before !== undefined) queryParams.before = params.before;
        if (params?.after !== undefined) queryParams.after = params.after;

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                messages?: IMessage[];
                has_more?: boolean;
            };
            error?: string;
        }>(`${EnhancedApi.CHATROOMS}/${roomId}/messages`, queryParams);

        const data = handleApiResponse(response, "Failed to get messages");

        return {
            messages: data.messages || [],
            has_more: data.has_more || false,
        };
    }

    /**
     * Sends a message to a chatroom with optional reply functionality.
     *
     * @param roomId - The Matrix room ID to send message to
     * @param content - The message content (will be sanitized for XSS prevention)
     * @param type - The message type (default: "m.text")
     * @param replyTo - Optional event ID to reply to
     * @returns Promise resolving to the sent message
     * @throws SynapseEnhancedError on API failure or invalid input
     */
    public async sendMessage(
        roomId: string,
        content: string,
        type: string = "m.text",
        replyTo?: string,
    ): Promise<IMessage> {
        validateRoomId(roomId);
        this.checkRateLimit("sendMessage");

        if (!content || typeof content !== "string") {
            throw this.createError("Message content is required and must be a string", ErrorCode.INVALID_PARAM);
        }

        const sanitizedContent = sanitizeContent(content, { maxLength: MessageLimits.MAX_CONTENT_LENGTH });
        const body: Record<string, unknown> = {
            content: sanitizedContent,
            msgtype: type,
        };
        if (replyTo) body["m.relates_to"] = { ["m.in_reply_to"]: { event_id: replyTo } };

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                message?: IMessage;
            };
            error?: string;
        }>(`${EnhancedApi.CHATROOMS}/${roomId}/messages`, body);

        const data = handleApiResponse(response, "Failed to send message");

        return (
            data.message || {
                message_id: "",
                room_id: roomId,
                content: content,
                type: type,
                sender: "",
                timestamp: new Date().toISOString(),
                reply_to: replyTo,
                is_deleted: false,
            }
        );
    }

    /**
     * Deletes a message from a chatroom.
     *
     * @param roomId - The Matrix room ID containing the message
     * @param messageId - The message event ID to delete
     * @returns Promise resolving to true on success
     * @throws SynapseEnhancedError on API failure or invalid input
     */
    public async deleteMessage(roomId: string, messageId: string): Promise<boolean> {
        validateRoomId(roomId);
        validateMessageId(messageId);
        this.checkRateLimit("deleteMessage");

        const response = await this.httpClient.delete<{
            status: string;
            error?: string;
        }>(`${EnhancedApi.CHATROOMS}/${roomId}/messages/${encodeURIComponent(messageId)}`);

        handleApiResponse(response, "Failed to delete message");
        return true;
    }

    /**
     * Searches for messages in a chatroom matching a query string.
     *
     * @param roomId - The Matrix room ID to search in
     * @param params - Search parameters
     * @param params.query - The search query string (required)
     * @param params.page - Page number for pagination (default: 1)
     * @param params.limit - Maximum number of results (default: 50)
     * @returns Promise resolving to matching messages and total count
     * @throws SynapseEnhancedError on API failure or invalid input
     */
    public async searchMessages(
        roomId: string,
        params: ISearchMessagesParams,
    ): Promise<{ messages: IMessage[]; total: number }> {
        validateRoomId(roomId);
        this.checkRateLimit("searchMessages");

        if (!params.query || typeof params.query !== "string") {
            throw this.createError("Search query is required and must be a string", ErrorCode.INVALID_PARAM);
        }

        const queryParams: Record<string, string | number | undefined> = {
            room_id: roomId,
            query: params.query,
            page: params.page || PaginationDefaults.PAGE,
            limit: params.limit || PaginationDefaults.LIMIT,
        };

        const response = await this.httpClient.get<{
            status: string;
            data?: {
                messages?: IMessage[];
                total?: number;
            };
            error?: string;
        }>(EnhancedApi.MESSAGES_SEARCH, queryParams);

        const data = handleApiResponse(response, "Failed to search messages");

        return {
            messages: data.messages || [],
            total: data.total || 0,
        };
    }
}
